def make_finding(item, ordinal, refs):
    fid, name, primary = item
    low = name.lower()
    kinds = [primary if primary in KINDS else "other", KINDS[(ordinal + 7) % len(KINDS)], KINDS[(ordinal + 16) % len(KINDS)]]
    return {
        "id": fid,
        "name": name,
        "description": f"Records {low} as source-qualified return/refund context while order, fulfilment, item, shipment, inventory, invoice, payment, warranty, recall, dispute and records masters remain independently identifiable.",
        "source_refs": refs,
        "questions": [
            {"id": f"{fid}-q01", "text": f"Which stable case, version, source-transaction, subject, party and external-master identifiers plus explicit profile and unknown state establish {low}?", "kind": kinds[0], "answer_data": ["case and version IDs", "external master references", "profile, assertion status and mastering system"]},
            {"id": f"{fid}-q02", "text": f"Which requested, asserted, observed, authorized, rejected, corrected or superseded state of {low} applies, to what scope, under which rule and authority?", "kind": kinds[1], "answer_data": ["state axis and scope", "rule, authority and reason", "predecessor and successor assertions"]},
            {"id": f"{fid}-q03", "text": f"What evidence, method, actor, event time, observation time, confidence, access marking and validation rule support {low}, and what remains unknown or disputed?", "kind": kinds[2], "answer_data": ["evidence and method", "actor and distinct times", "confidence, access, validation and conflict"]},
        ],
        "data_elements": [{"id": f"{fid}-data", "name": f"{name} data", "description": f"Structured fields for {low}, including stable identity, external references, value or state, scope, authority, source, times, confidence, access and conflict status.", "value_kind": "object", "cardinality": "0..n", "required": False, "source_refs": refs}],
        "artifacts": [{"id": f"{fid}-record", "name": f"{name} record", "description": f"Immutable or versioned evidence record for {low} with declared profile and projection loss.", "media_or_form": ["application/yaml", "application/json", "text/markdown"], "serial": True, "identity_strategy": f"Return/refund case ID plus independent version, source, subject, decision, movement, adjustment, payment or event ID and artifact kind for {fid}; party, order number, date, amount, filename or digest never identifies the case alone.", "source_refs": refs}],
        "inline_only_rationale": None,
    }


def structure():
    bundles = []
    ordinal = 0
    for bid, bname, rationale, layers in ROWS:
        built_layers = []
        bundle_refs = []
        for lid, lname, refs, items in layers:
            findings = []
            for item in items:
                findings.append(make_finding(item, ordinal, refs))
                ordinal += 1
            built_layers.append({"id": lid, "name": lname, "description": f"Groups {lname.lower()} for the governed return/refund case.", "source_refs": refs, "findings": findings})
            bundle_refs.extend(refs)
        bundles.append({"id": bid, "name": bname, "description": f"Groups {bname.lower()} without duplicating authoritative sibling lifecycles.", "rationale": rationale, "source_refs": list(dict.fromkeys(bundle_refs)), "layers": built_layers})
    return {"bundles": bundles}


